//! Code generated by `topics!`: one module per level, holding `Topic`,
//! `Steps`, the group enums and the child modules.
//!
//! Generated names (`Topic::Push`, `PushQueue`, the `push` method and module)
//! carry the span of the topic name, so editors go to its declaration.

use proc_macro2::{TokenStream, TokenTree};
use quote::{format_ident, quote};
use syn::ext::IdentExt;
use syn::{AttrStyle, Attribute, Ident, LitStr};

use crate::parse::{Entry, GroupEnum, Input, Kind};

pub fn expand(input: &Input) -> TokenStream {
    let cx = Cx {
        krate: &input.krate,
        attrs: &input.attrs,
    };
    cx.module(&input.root, "")
}

struct Cx<'a> {
    krate: &'a TokenTree,
    /// Applied to every `Topic` enum.
    attrs: &'a [Attribute],
}

impl Cx<'_> {
    /// The module of the level `entry`, on `subject`.
    fn module(&self, entry: &Entry, subject: &str) -> TokenStream {
        let Kind::Level(children) = &entry.kind else {
            unreachable!("only levels have a module")
        };
        let k = self.krate;
        let (docs, name, attrs) = (&entry.docs, &entry.name, self.attrs);
        let (mut variants, mut arms, mut methods, mut items) = (vec![], vec![], vec![], vec![]);
        for child in children {
            let [variant, arm, method, item] = self.child(child, subject);
            variants.push(variant);
            arms.push(arm);
            methods.push(method);
            items.push(item);
        }
        // declared with the span of the level's name, to go there from them
        let topic = Ident::new("Topic", name.span());
        let steps = Ident::new("Steps", name.span());
        let groups = entry.groups.as_ref().map(|groups| {
            let queue = Ident::new("Queue", name.span());
            self.group_enum(&queue, &topic, groups, "Queue groups of this level.")
        });
        // without children, `match self {}` would need `&Topic` to be empty
        let step = if arms.is_empty() {
            quote!(match *self {})
        } else {
            quote!(match self { #(#arms)* })
        };

        quote! {
            #(#docs)*
            pub mod #name {
                #[allow(unused_imports)]
                use super::*;

                #groups

                #(#attrs)*
                /// Messages of this level: one variant per child topic.
                #[allow(clippy::enum_variant_names)]
                pub enum #topic { #(#variants,)* }

                impl #k::Level for Topic {
                    fn step(&self) -> #k::Step<'_> {
                        #step
                    }
                }

                /// Navigation from this level: one method per child, used by `at!`.
                pub struct #steps<P>(#k::Channel<Topic, P>);

                // method names are topic names, so naming conventions don't apply
                #[allow(clippy::new_ret_no_self, clippy::wrong_self_convention, clippy::should_implement_trait)]
                impl<P: 'static> Steps<P> {
                    #(#methods)*
                }

                impl #k::Navigable for Topic {
                    type Steps<P: 'static> = Steps<P>;
                    fn steps<P: 'static>(channel: #k::Channel<Topic, P>) -> Steps<P> {
                        Steps(channel)
                    }
                }

                impl<P: 'static> #k::IntoChannel for Steps<P> {
                    type T = Topic;
                    type P = P;
                    type S = Topic;
                    fn into_channel(self) -> #k::Channel<Topic, P> {
                        self.0
                    }
                }

                #(#items)*
            }
        }
    }

    /// What `entry` adds to its parent, on `parent`: its `Topic` variant,
    /// `Level::step` arm, `Steps` method, and module or group enum.
    fn child(&self, entry: &Entry, parent: &str) -> [TokenStream; 4] {
        let k = self.krate;
        let name = &entry.name;
        let seg = name.unraw().to_string();
        let lit = LitStr::new(&seg, name.span());
        let var = Ident::new(&camel(&seg), name.span());
        let mut subject = if parent.is_empty() {
            seg
        } else {
            format!("{parent}.{seg}")
        };
        if entry.param.is_some() {
            subject.push_str(".*");
        }
        let docs = &entry.docs;
        let gap = (!docs.is_empty()).then(|| quote!(#[doc = ""]));
        let about = format!("Subject `{subject}`.");
        let doc = quote!(#(#docs)* #gap #[doc = #about]);

        let (inner, bind, next) = match &entry.kind {
            Kind::Level(_) => (quote!(#name::Topic), quote!(x), quote!(Some(x))),
            Kind::Mount(module) => (quote!(#module::Topic), quote!(x), quote!(Some(x))),
            Kind::Leaf { msg, .. } => (quote!(#msg), quote!(_), quote!(None)),
        };
        let (variant, arm) = match &entry.param {
            None => (
                quote!(#doc #var(#inner)),
                quote!(Topic::#var(#bind) => #k::Step { name: #lit, param: None, next: #next },),
            ),
            Some(param) => (
                quote!(#doc #var(#param, #inner)),
                quote! {
                    Topic::#var(p, #bind) => #k::Step {
                        name: #lit, param: Some(p as &dyn #k::ParamValue), next: #next,
                    },
                },
            ),
        };

        // the method: `name(self)`, or `name(self, select)` adding the
        // wildcard of a parameter to the channel's params `P`
        let (generics, select, params, bound, step) = match &entry.param {
            None => (
                quote!(),
                quote!(),
                quote!(P),
                quote!(),
                quote! {
                    #k::Plain::new(
                        #lit,
                        |a: &Topic| match a {
                            Topic::#var(x) => Some(x),
                            #[allow(unreachable_patterns)]
                            _ => None,
                        },
                        Topic::#var,
                    )
                },
            ),
            Some(param) => (
                quote!(<S: #k::Param<#param>>),
                quote!(, select: S),
                quote!(#k::Append<P, S::Q>),
                quote!(where P: #k::AppendParams<S::Q>),
                quote! {
                    #k::ParamStep::new(
                        #lit,
                        select,
                        |a: &Topic| match a {
                            Topic::#var(v, x) => Some((v, x)),
                            #[allow(unreachable_patterns)]
                            _ => None,
                        },
                        Topic::#var,
                    )
                },
            ),
        };
        let (ret, body, item) = match &entry.kind {
            Kind::Level(_) => (
                quote!(#name::Steps<#params>),
                quote!(<#name::Topic as #k::Navigable>::steps(self.0.step(#step))),
                self.module(entry, &subject),
            ),
            Kind::Mount(module) => (
                quote!(#module::Steps<#params>),
                quote!(<#module::Topic as #k::Navigable>::steps(self.0.step(#step))),
                quote!(),
            ),
            Kind::Leaf { msg, reply } => {
                // the leaf's scope is its group enum, or for a request leaf
                // without groups an empty enum: the message type may be used
                // by other leaves
                let (scope, mut item) = match (&entry.groups, reply) {
                    (None, None) => (None, quote!()),
                    (Some(groups), _) => {
                        let queue = format_ident!("{}Queue", var);
                        let doc = "Queue groups of this topic.";
                        let item = self.group_enum(&queue, &queue, groups, doc);
                        (Some(queue), item)
                    }
                    (None, Some(_)) => {
                        let scope = format_ident!("{}Scope", var);
                        let doc = format!("Scope of the request leaf `{subject}`.");
                        (
                            Some(scope.clone()),
                            quote!(#[doc = #doc] pub enum #scope {}),
                        )
                    }
                };
                // a request leaf answers, any other leaf publishes; without
                // scope, the leaf publishes through `impl<T> Publish<T> for T`
                match (&scope, reply) {
                    (Some(scope), Some(reply)) => item.extend(quote! {
                        impl #k::Answer<#msg> for #scope {
                            type Reply = #reply;
                        }
                    }),
                    (Some(scope), None) => {
                        item.extend(quote!(impl #k::Publish<#msg> for #scope {}))
                    }
                    (None, _) => {}
                }
                match scope {
                    None => (
                        quote!(#k::Channel<#msg, #params>),
                        quote!(self.0.step(#step)),
                        item,
                    ),
                    Some(scope) => (
                        quote!(#k::Channel<#msg, #params, #scope>),
                        quote!(self.0.step(#step).with_scope()),
                        item,
                    ),
                }
            }
        };
        let method = quote! {
            #doc
            pub fn #name #generics(self #select) -> #ret #bound {
                #body
            }
        };
        [variant, arm, method, item]
    }

    /// Group enum `name`, joinable on channels of the scope `scope`.
    fn group_enum(
        &self,
        name: &Ident,
        scope: &Ident,
        groups: &GroupEnum,
        doc: &str,
    ) -> TokenStream {
        let k = self.krate;
        let attrs = groups.attrs.iter().map(|attr| Attribute {
            style: AttrStyle::Outer,
            ..attr.clone()
        });
        let variants = groups.variants.iter();
        quote! {
            #[doc = #doc]
            #(#attrs)*
            #[derive(Clone, PartialEq, Eq, Hash)]
            pub enum #name { #(#variants),* }

            impl #k::QueueGroup for #name {}
            impl #k::InScope<#scope> for #name {}
        }
    }
}

/// `pull_request` is `PullRequest`.
fn camel(name: &str) -> String {
    name.split('_')
        .flat_map(|word| {
            let mut chars = word.chars();
            let first = chars.next().into_iter().flat_map(char::to_uppercase);
            first.chain(chars)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::camel;

    #[test]
    fn camel_case() {
        assert_eq!(camel("push"), "Push");
        assert_eq!(camel("pull_request"), "PullRequest");
        assert_eq!(camel("a__b_"), "AB");
    }
}
